// 다른 주문의 변화가 클릭 대상의 DOM을 교체하지 않도록 주문 ID별 요소를 유지한다.
function updateOrderBoard(panel){
 const grid=panel.querySelector('.order-grid'),empty=panel.querySelector('.order-empty');
 if(!grid||!empty||typeof document.createElement!=='function')return false;
 const existing=new Map(Array.from(grid.querySelectorAll('[data-order-card]')).map(node=>[node.dataset.orderCard,node]));
 for(const customer of state.customers){
  const key=String(customer.id),menu=menus.find(m=>m.id===customer.menu);let card=existing.get(key);
  if(card)existing.delete(key);else{card=document.createElement('div');card.className='card order-card';card.dataset.orderCard=key;grid.appendChild(card)}
  if(card.dataset.orderStatus!==customer.status){card.dataset.orderStatus=customer.status;card.innerHTML=orderCardContent(customer);bindOrderButtons(card)}
  let shortage=card.querySelector('[data-shortage]');const missing=customer.status==='waiting'?missingIngredients(menu).map(x=>x.name+' '+x.count+'개 부족').join(' · '):'';if(shortage){shortage.textContent=missing;shortage.hidden=!missing}else if(missing){const action=card.querySelector('.order-action');if(action){shortage=document.createElement('span');shortage.className='order-shortage';shortage.dataset.shortage=key;shortage.textContent=missing;action.prepend(shortage)}}
  const button=card.querySelector('[data-make],[data-serve]');
  if(button){const unavailable=customer.status==='waiting'&&!hasStock(menu);button.disabled=!!state.workers.taki||unavailable||tutorialBlocks(customer.id,customer.status==='waiting'?'make':'serve');if(customer.status==='waiting')button.textContent=unavailable?'재료 부족':'직접 제조';const cancel=card.querySelector('[data-cancel]');if(cancel){cancel.hidden=!unavailable;cancel.disabled=tutorialBlocks(customer.id,'make')}}
 }
 for(const node of existing.values())node.remove();
 empty.hidden=state.customers.length>0;empty.textContent=emptyOrderText();updateOrderTimers(panel);return true;
}
function updateOrderTimers(panel){for(const k of ['taki']){const node=panel.querySelector('[data-worker=\"'+k+'\"]');if(node)node.textContent=workerText(k)}for(const customer of state.customers){const label=panel.querySelector('[data-patience=\"'+customer.id+'\"]'),bar=panel.querySelector('[data-patience-bar=\"'+customer.id+'\"]');if(label)label.textContent='기다림 '+Math.max(0,customer.patience)+'초';if(bar){bar.style.width=Math.max(0,customer.patience/customer.maxPatience*100)+'%';bar.classList.toggle('low',customer.patience<10)}}}
function stockRecommendation(){
 const previous=state.menuHistory.yesterday,used={beans:0,milk:0,cake:0,matcha:0},fallback={coffee:5,latte:3,cake:7,matcha:3,liveSet:2};let includesNew=false;
 for(const m of menus){if(!state.enabled[m.id]||(m.limited&&!specialDay()))continue;const history=previous?.[m.id];if(previous&&!history)includesNew=true;const count=history?Math.max(1,Math.floor(history.sold||0)):fallback[m.id];for(const [k,n] of Object.entries(m.needs))used[k]+=count*n}
 let includedShortages=false;if(previous)for(const k of Object.keys(used))if(used[k]){const extra=state.previousFailures?.missing[k]||0;if(extra)includedShortages=true;used[k]+=1+extra}
 const missing=Object.fromEntries(Object.keys(used).map(k=>[k,Math.max(0,used[k]-state.stock[k])]));return {missing,cost:Object.entries(missing).reduce((sum,[k,n])=>sum+ingredients[k].cost*n,0),basedOnPrevious:!!previous,includesNew,includedShortages,shortagePartial:!!state.previousFailures&&!state.previousFailures.complete};
}
function buyRecommendation(){if(state.phase!=='prep')return false;const {missing,cost}=stockRecommendation();if(!cost||state.money<cost)return false;for(const [k,n] of Object.entries(missing))state.stock[k]+=n;state.money-=cost;state.expense+=cost;state.accounting.purchases+=cost;beep('purchase');render();return true}
