function vnCast(story, index, line){
  if(Array.isArray(line[3]?.cast))return line[3].cast.slice();
  const current=line[0], known=['타키','토모리','아논','라나','소요','사키코','무츠미','우이카','우미리','냐무','하루','메이','준'];
  if(!known.includes(current))return [current];
  let other=null;
  for(let i=Math.min(index-1,story.lines.length-1);i>=0;i--){const name=story.lines[i][0];if(name!==current&&known.includes(name)){other=name;break}}
  if(!other)for(let i=index+1;i<story.lines.length;i++){const name=story.lines[i][0];if(name!==current&&known.includes(name)){other=name;break}}
  if(!other)return [current];
  // 첫 발화자에게 왼쪽 자리를 고정한다.
  const first=story.lines.find(l=>l[0]===current||l[0]===other)?.[0];
  return first===current?[current,other]:[other,current];
}
