  document.querySelectorAll('.vn-cast:not(.vn-exit-layer) .vn-slot').forEach(slot=>{const old=retainedVnSlots.get(slot.dataset.actor);if(!old)return;old.className=slot.className;old.setAttribute('style',slot.getAttribute('style'));const oldImage=old.querySelector('img'),newImage=slot.querySelector('img');if(oldImage&&newImage){oldImage.className=newImage.className;oldImage.alt=newImage.alt}slot.replaceWith(old)});
