function titleLoad(snapshot){
 if(!validBackupState(snapshot))throw Error('불러올 수 없는 저장 데이터입니다.');
 try{localStorage.setItem(KEY,JSON.stringify(snapshot))}catch{throw Error('불러온 진행을 저장하지 못했습니다. 현재 진행은 유지됩니다.')}
 // Slots produced by this version are complete snapshots: restore in place so
 // the decoded portrait pool survives. Older incomplete snapshots use bootstrap migration.
 if(snapshot.workModel==='solo-v1'&&Object.keys(initial()).every(key=>Object.hasOwn(snapshot,key))){
  stopVnAuto();stopVnTyping();clearServiceNotice();activeStory=null;modalOpen=false;menuPaused=false;state=JSON.parse(JSON.stringify(snapshot));storageMode='ok';tab=state.phase==='prep'?'prep':'orders';selectedOrderId=null;lastPanelTab=null;workerSignature=null;applyPreferences();window.RingTitle?.finishLoad();titleResume();return;
 }
 try{sessionStorage.setItem('project-ring-resume-once','yes')}catch{}
 window.location.reload();
}
function titleAdapter(){return {
 snapshot:()=>JSON.parse(JSON.stringify(state)),validate:validBackupState,hasProgress:titleHasProgress,save:()=>{save();return storageMode==='ok'},beep,
 describe:snapshot=>snapshot.pendingStory?storyData[snapshot.pendingStory.id]?.title||'이야기 진행 중':snapshot.phase==='open'?'카페 영업 중':snapshot.phase==='closed'?'영업 정산':'영업 준비',
 pause:()=>{stopVnAuto();completeVnText();stopVnTyping();vnMenuOpen=false},
 resumeView:()=>{if(activeStory){drawStory();completeVnText();$('#app').inert=true}else{$('#app').inert=modalOpen;if(!modalOpen)render()}},
 preference:(key,value)=>{if(['sound','volume','vnSpeed','reduceMotion'].includes(key)){state[key]=value;applyPreferences();save()}},
 stopMusic:()=>{const drawer=$('.music-drawer');if(drawer)drawer.open=false},
 newGame:titleNewGame,continueGame:titleResume,load:titleLoad
}}

$('#tutorialSkip').onclick=skipTutorial;
$('#guideBtn').onclick=()=>{modalOpen=true;$('#app').inert=true;$('#modal').classList.remove('hidden');$('#dialog').innerHTML=`<div class="eyebrow">HOW TO PLAY</div><h2>RiNG 영업 안내</h2><p>1. <strong>준비</strong> 탭에서 재료를 사고 메뉴 가격과 타키의 업무를 정하세요.</p><p>2. <strong>영업 시작</strong> 후 주문을 눌러 타키에게 제조와 서빙을 지시하세요. 자동 우선순위도 선택할 수 있습니다.</p><p>3. 기다림이 길어지면 손님이 떠납니다. 공연 일정과 날씨에 따라 수요가 달라지고, 특별 공연일에는 한정 세트를 팔 수 있어요.</p><p>4. 정산 후 이야기와 다음 영업일로 이어집니다. 진행은 이 브라우저에 자동 저장됩니다.</p><div class="actions"><button id="guideClose" class="primary">확인</button></div>`;$('#guideClose').onclick=()=>{modalOpen=false;$('#modal').classList.add('hidden');$('#app').inert=false;render();$('#guideBtn').focus?.()};$('#guideClose').focus?.()};$('#settingsBtn').onclick=()=>{modalOpen=true;$('#app').inert=true;$('#modal').classList.remove('hidden');$('#dialog').innerHTML=`<h2>설정</h2><button id="openBgmSettings">배경 음악 설정</button><div class="card row"><span>효과음</span><button id="sound">${state.sound?'켜짐':'꺼짐'}</button></div><label class="card row" for="volume"><span>효과음 크기</span><input id="volume" type="range" min="0" max="100" value="${Math.round((state.volume??0.2)*100)}"></label><label class="card row" for="readerSpeed"><span>대사 글자 속도</span><select id="readerSpeed"><option value="30" ${(state.vnSpeed??30)===30?'selected':''}>보통</option><option value="12" ${state.vnSpeed===12?'selected':''}>빠르게</option><option value="0" ${state.vnSpeed===0?'selected':''}>즉시</option></select></label><label class="card row" for="autoDelay"><span>자동 진행 간격</span><select id="autoDelay"><option value="1000" ${state.vnAutoDelay===1000?'selected':''}>빠르게</option><option value="1800" ${(state.vnAutoDelay??1800)===1800?'selected':''}>보통</option><option value="3500" ${state.vnAutoDelay===3500?'selected':''}>느리게</option></select></label><label class="card row" for="textSize"><span>대사 글자 크기</span><select id="textSize"><option value="normal" ${state.vnTextSize!=='large'?'selected':''}>보통</option><option value="large" ${state.vnTextSize==='large'?'selected':''}>크게</option></select></label><label class="card row" for="reduceMotion"><span>움직임 줄이기</span><input id="reduceMotion" type="checkbox" ${state.reduceMotion?'checked':''}></label><div class="sound-preview"><span>소리 미리 듣기</span><button data-sample="door">문종</button><button data-sample="brew">커피 추출</button><button data-sample="serve">계산</button><button data-sample="result">정산</button></div><div class="card"><strong>진행 백업</strong><p class="muted">진행은 이 브라우저에 자동 저장됩니다. 다른 브라우저로 옮기거나 보관하려면 백업 파일을 내려받으세요. 복원하면 이 브라우저의 현재 진행을 덮어씁니다.</p><button id="saveExport">백업 내려받기</button> <label class="backup-import" for="restoreFile">백업 파일 복원</label><input id="restoreFile" type="file" accept="application/json,.json"><p id="saveFeedback" class="muted" role="status"></p></div><p class="muted">PROJECT RiNG은 비공식 팬게임입니다.</p><div class="actions"><button id="reset">새 게임</button><button id="done" class="primary">닫기</button></div>`;$('#openBgmSettings').onclick=()=>window.RingTitle?.open('settings');document.querySelectorAll('[data-sample]').forEach(b=>b.onclick=()=>beep(b.dataset.sample));$('#readerSpeed').onchange=e=>{state.vnSpeed=Number(e.target.value);save()};$('#autoDelay').onchange=e=>{state.vnAutoDelay=Number(e.target.value);save()};$('#textSize').onchange=e=>{state.vnTextSize=e.target.value==='large'?'large':'normal';applyPreferences();save()};$('#reduceMotion').onchange=e=>{state.reduceMotion=!!e.target.checked;applyPreferences();save()};$('#saveExport').onclick=exportBackup;$('#restoreFile').onchange=e=>restoreBackup(e.target);$('#volume').oninput=e=>{state.volume=Number(e.target.value)/100;save();beep('cup')};$('#sound').onclick=()=>{state.sound=!state.sound;save();$('#sound').textContent=state.sound?'켜짐':'꺼짐';beep('choice')};$('#done').onclick=()=>{modalOpen=false;$('#modal').classList.add('hidden');$('#app').inert=false;render();$('#settingsBtn').focus?.()};$('#done').focus?.();$('#reset').onclick=()=>{if(confirm('저장된 진행을 지우고 새로 시작할까요?')){storageMode='ok';clearServiceNotice();state=initial();tab='prep';menuPaused=false;modalOpen=false;$('#modal').classList.add('hidden');$('#app').inert=false;applyPreferences();render()}}};$('#priority').onchange=e=>{if(['manual','make','serve','rest'].includes(e.target.value)){state.priority=e.target.value;save()}};document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));setInterval(tick,1000);window.RingExperience?.mount({getState:()=>state,render,openDay,setTab,assign,summary,save,beep,selectOrder,replayIntro:()=>showStory('intro',true)});applyPreferences();render();if(window.RingTitle){window.RingTitle.mount(titleAdapter());const menu=$('#systemMenu');if(menu)menu.onclick=()=>window.RingTitle.open()}else if(state.pendingStory&&storyData[state.pendingStory.id])showStory(state.pendingStory.id,false,Math.min(state.pendingStory.index,storyData[state.pendingStory.id].lines.length));else if(state.phase==='closed')summary();

